"""Editorial mission section and a code-native illustration of shared defense."""
import math

def globe_fallback():
    points=[]
    for i in range(840):
        y=1-2*(i+.5)/840; r=math.sqrt(1-y*y); a=i*2.39996323
        x,z=math.cos(a)*r,math.sin(a)*r
        px=320+x*227;py=320+y*227
        alpha=.12+.56*(z+1)/2
        points.append(f'<circle cx="{px:.1f}" cy="{py:.1f}" r="{.7+(z+1)*.45:.1f}" fill="#b4e7c9" opacity="{alpha:.2f}"/>')
    return '<svg class="globe-fallback" viewBox="0 0 640 640" aria-hidden="true"><g fill="none" stroke="#85cbb0" stroke-opacity=".16"><circle cx="320" cy="320" r="228"/><ellipse cx="320" cy="320" rx="228" ry="88" transform="rotate(-26 320 320)"/><ellipse cx="320" cy="320" rx="228" ry="158" transform="rotate(-26 320 320)"/><ellipse cx="320" cy="320" rx="89" ry="228" transform="rotate(-26 320 320)"/></g>'+''.join(points)+'</svg>'

